type TabsProps = {
  activeTab: 'home' | 'settings'
  onTabChange: (tab: 'home' | 'settings') => void
}

export default function Tabs({ activeTab, onTabChange }: TabsProps) {
  return (
    <div className="flex border-b border-gray-200 dark:border-gray-700 mb-4 bg-white dark:bg-gray-800 rounded-lg shadow-sm">
      <button
        className={`px-6 py-3 font-medium transition-colors ${
          activeTab === 'home'
            ? 'border-b-2 border-blue-600 text-blue-600 bg-blue-50 dark:bg-blue-900/20'
            : 'text-gray-500 dark:text-gray-300 hover:text-gray-700 dark:hover:text-gray-200'
        }`}
        onClick={() => onTabChange('home')}
      >
        Home
      </button>
      <button
        className={`px-6 py-3 font-medium transition-colors ${
          activeTab === 'settings'
            ? 'border-b-2 border-blue-600 text-blue-600 bg-blue-50 dark:bg-blue-900/20'
            : 'text-gray-500 dark:text-gray-300 hover:text-gray-700 dark:hover:text-gray-200'
        }`}
        onClick={() => onTabChange('settings')}
      >
        Settings
      </button>
    </div>
  )
}